// <auto-generated/>
// ReportExportHttp — the HTTP side of report export (docs/features/api-contract.md, "Report
// export"). Generated report list routes call it when a `report-export` generator is wired;
// it reads `?format=`, builds the three 400 envelopes and writes the download.
//
// The selector is the `format` query parameter and nothing else: Accept headers are never
// consulted. Matching is case-sensitive and an empty value is unknown. Nothing here knows a
// report's columns: the per-report export module the generator emits owns those, and writes
// through a TextWriter this helper hands it.
//
// Reusable by a future entity export; wired for report routes only. BCL + ASP.NET Core only.

#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;

namespace MetaObjects.Codegen.Runtime;

/// <summary>Format selection, refusals and attachment responses for a report export.</summary>
public static class ReportExportHttp
{
    /// <summary>The formats a route wires, in the order the <c>invalid_format</c> envelope lists them.</summary>
    public static readonly IReadOnlyList<string> Formats = ["csv", "json", "xml"];

    /// <summary>The raw <c>?format=</c> value, or <c>null</c> when the request carries none. An empty value is a value.</summary>
    public static string? Requested(IQueryCollection query) =>
        query.TryGetValue("format", out var format) ? format.ToString() : null;

    /// <summary>
    /// The refusal for a request that names a <paramref name="format"/>, or <c>null</c> when the export may
    /// proceed: <c>400 invalid_format</c> for anything but <c>csv</c>, <c>json</c>, <c>xml</c> (answered before any
    /// query runs), then <c>400 export_with_count</c> when <c>withCount</c> is truthy, since an export has no
    /// <c>{ rows, total }</c> envelope, JSON included. Always <c>null</c> for no format.
    /// </summary>
    public static IResult? Refuse(string? format, IQueryCollection query)
    {
        if (format is null) return null;
        if (!Formats.Contains(format, StringComparer.Ordinal))
            return Results.BadRequest(new { error = "invalid_format", expected = Formats });
        if (query.TryGetValue("withCount", out var wc)
            && (wc == "1" || string.Equals(wc, "true", StringComparison.OrdinalIgnoreCase)))
            return Results.BadRequest(new
            {
                error = "export_with_count",
                message = "withCount asks for a { rows, total } envelope, which an export cannot carry; drop withCount or drop format.",
            });
        return null;
    }

    /// <summary><c>400 export_too_large</c>: more rows than <paramref name="maxRows"/>, refused before a byte of body is written.</summary>
    public static IResult TooLarge(int maxRows) =>
        Results.BadRequest(new { error = "export_too_large", maxRows });

    /// <summary>
    /// The JSON export: the list route's rows through the host's configured JSON options (so a <c>wire</c>
    /// setting applies exactly as on the list route), as <c>application/json</c>, with the attachment header.
    /// </summary>
    public static IResult Json<T>(HttpContext http, string segment, IReadOnlyList<T> rows)
    {
        Attach(http, segment, "json");
        var options = http.RequestServices
            .GetService(typeof(Microsoft.Extensions.Options.IOptions<Microsoft.AspNetCore.Http.Json.JsonOptions>))
            is Microsoft.Extensions.Options.IOptions<Microsoft.AspNetCore.Http.Json.JsonOptions> configured
            ? configured.Value.SerializerOptions
            : null;
        return Results.Json(rows, options, "application/json");
    }

    /// <summary>The CSV export: <paramref name="write"/> fills a UTF-8 (no BOM of the encoder's own) body.</summary>
    public static IResult Csv(HttpContext http, string segment, Action<TextWriter> write) =>
        Body(http, segment, "csv", "text/csv; charset=utf-8", write);

    /// <summary>The XML export: <paramref name="write"/> fills a UTF-8 body served as <c>application/xml</c>.</summary>
    public static IResult Xml(HttpContext http, string segment, Action<TextWriter> write) =>
        Body(http, segment, "xml", "application/xml", write);

    /// <summary>Sets <c>Content-Disposition: attachment; filename="&lt;segment&gt;.&lt;ext&gt;"</c>.</summary>
    public static void Attach(HttpContext http, string segment, string extension) =>
        http.Response.Headers.ContentDisposition = $"attachment; filename=\"{segment}.{extension}\"";

    // The body is rendered fully before anything is sent: a writer that throws is a clean 500, and
    // the length is known. A report is materialised up to the cap in this version (no streaming).
    private static IResult Body(HttpContext http, string segment, string extension, string contentType, Action<TextWriter> write)
    {
        using var buffer = new MemoryStream();
        using (var writer = new StreamWriter(buffer, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false), 4096, leaveOpen: true))
            write(writer);
        Attach(http, segment, extension);
        return new Download(contentType, buffer.ToArray());
    }

    private sealed class Download(string contentType, byte[] bytes) : IResult
    {
        public async Task ExecuteAsync(HttpContext httpContext)
        {
            httpContext.Response.StatusCode = StatusCodes.Status200OK;
            httpContext.Response.ContentType = contentType;
            httpContext.Response.ContentLength = bytes.Length;
            await httpContext.Response.Body.WriteAsync(bytes);
        }
    }
}
